import type { InjectionKey } from 'vue'

// What an Accordion gives its items: whether a value is open, and the press that opens or closes it.
export type AccordionContext = { isOpen: (v: string) => boolean, toggle: (v: string) => void }
export const accordionKey: InjectionKey<AccordionContext> = Symbol('accordion')

'use client'
import type { ReactNode } from 'react'
import { AccordionContext } from '@/react/hooks/useAccordion'
import { useControllable } from '@/react/hooks/useControllable'
import { cn } from '@/react/lib/cn'

// A stack of disclosures, built in Conare's style from the console's disclosure (.v2-collapse, .c-details) and the
// website's FAQ: hairlines between rows, a 12px muted chevron that turns as a row opens, the row's height opening from
// 0fr to 1fr over 260ms and closing in 180ms on the strong ease-out, its words fading down into place a beat after.
// One open at a time by default (a second press closes it); `multiple` lets several stay open. Vue's v-model is
// `value` with `onValueChange` (or `defaultValue` alone): the open item's value (or the list of them with `multiple`).
// Compose with AccordionItem.
export type AccordionValue = string | string[] | null
export interface AccordionProps {
  multiple?: boolean
  value?: AccordionValue
  defaultValue?: AccordionValue
  onValueChange?: (value: AccordionValue) => void
  className?: string
  children?: ReactNode
}

export function Accordion({ multiple, value, defaultValue = null, onValueChange, className, children }: AccordionProps) {
  const [model, setModel] = useControllable<AccordionValue>(value, defaultValue, onValueChange)
  const list = Array.isArray(model) ? model : model ? [model] : []
  const ctx = {
    isOpen: (v: string) => list.includes(v),
    toggle: (v: string) => {
      if (multiple) setModel(list.includes(v) ? list.filter(x => x !== v) : [...list, v])
      else setModel(list.includes(v) ? null : v)
    },
  }
  return (
    <AccordionContext.Provider value={ctx}>
      <div data-ds="accordion" className={cn('ds-accordion border-t border-edge', className)}>{children}</div>
    </AccordionContext.Provider>
  )
}

export default Accordion

'use client'
import { useId, type ReactNode } from 'react'
import { ChevronDown } from 'lucide-react'
import { useAccordion } from '@/react/hooks/useAccordion'
import { cn } from '@/react/lib/cn'

// One row of an Accordion: the question as a full-width button (40px, 13px soft text that turns ink under the pointer
// and while open) over a hairline, and the answer under it. The closed answer is inert, so its links leave the tab
// order. `title` names the row (a string, or a node for Vue's `title` slot); children are the answer.
export interface AccordionItemProps { value: string, title?: ReactNode, disabled?: boolean, children?: ReactNode }

export function AccordionItem({ value, title, disabled, children }: AccordionItemProps) {
  const ctx = useAccordion()
  const open = ctx?.isOpen(value) ?? false
  const id = useId()
  return (
    <>
      <style href="ds-accordion-item" precedence="ds">{css}</style>
      <div data-ds="accordion-item" className="border-b border-edge" data-open={open}>
        <h3>
          <button
            id={`${id}-head`}
            type="button"
            aria-expanded={open}
            aria-controls={`${id}-body`}
            disabled={disabled}
            className="flex min-h-row w-full cursor-pointer items-center justify-between gap-3 py-2 text-left type-ui text-fg-soft transition-colors duration-120 ease-standard hover:text-fg aria-expanded:text-fg disabled:cursor-default disabled:text-fg-muted"
            onClick={() => ctx?.toggle(value)}
          >
            {title}
            <ChevronDown size={12} strokeWidth={1.5} aria-hidden="true" className={cn('shrink-0 text-fg-muted transition-[rotate] duration-200 ease-standard motion-reduce:transition-none', open && 'rotate-180')} />
          </button>
        </h3>
        <div id={`${id}-body`} role="region" aria-labelledby={`${id}-head`} inert={!open} className="ds-collapse" data-open={open}>
          <div><div className="ds-collapse-body pb-3 type-ui text-fg-soft">{children}</div></div>
        </div>
      </div>
    </>
  )
}

export default AccordionItem

const css = `
/* The console's disclosure (console2.css .v2-collapse): open over 260ms, close in 180ms, the words fading and
   settling 6px down with a 2px blur that clears, so the text never pops. Reduced motion: no height or move, opacity only. */
.ds-collapse { display: grid; grid-template-rows: 0fr; transition: grid-template-rows var(--ds-duration-slide) var(--ds-easing-out); }
.ds-collapse[data-open="true"] { grid-template-rows: 1fr; transition-duration: var(--ds-duration-collapse); }
.ds-collapse > div { min-height: 0; overflow: hidden; }
.ds-collapse-body { opacity: 0; filter: blur(2px); transform: translateY(-6px); transition: opacity var(--ds-duration-micro) ease, filter var(--ds-duration-micro) ease, transform var(--ds-duration-slide) var(--ds-easing-out); }
.ds-collapse[data-open="true"] .ds-collapse-body { opacity: 1; filter: none; transform: none; transition: opacity var(--ds-duration-settle) ease 40ms, filter var(--ds-duration-settle) ease 40ms, transform var(--ds-duration-collapse) var(--ds-easing-out) 40ms; }
@media (prefers-reduced-motion: reduce) {
  .ds-collapse, .ds-collapse[data-open="true"] { transition: none; }
  .ds-collapse-body, .ds-collapse[data-open="true"] .ds-collapse-body { filter: none; transform: none; transition: opacity var(--ds-duration-micro) ease; }
}
`

'use client'
import { createContext, useContext } from 'react'

// What an Accordion gives its items: whether a value is open, and the press that opens or closes it.
export type AccordionContextValue = { isOpen: (v: string) => boolean, toggle: (v: string) => void }
export const AccordionContext = createContext<AccordionContextValue | null>(null)

/** The Accordion around an item, or null outside one. */
export function useAccordion() {
  return useContext(AccordionContext)
}

'use client'
import { useCallback, useRef, useState } from 'react'

// Vue's defineModel in React: a value that is controlled when the caller passes it (value + onValueChange, as Radix
// does) and kept inside otherwise (defaultValue). setValue calls onChange either way.
export function useControllable<T>(value: T | undefined, defaultValue: T, onChange?: (value: T) => void) {
	const [inner, setInner] = useState<T>(defaultValue)
	const controlled = value !== undefined
	const current = controlled ? value : inner
	const ref = useRef(onChange)
	ref.current = onChange
	const set = useCallback((next: T) => {
		if (!controlled) setInner(next)
		ref.current?.(next)
	}, [controlled])
	return [current, set] as const
}

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

