import { html, type PropertyValues } from 'lit'
import { DsElement, define, tagName } from '@/elements/lib/element'
import styles from 'virtual:tw'

// Accordion.vue as <conare-accordion>: a stack of disclosures, built in Conare's style from the console's disclosure
// (.v2-collapse, .c-details) and the website's FAQ: hairlines between rows, a 12px muted chevron that turns as a row
// opens, the row's height opening from 0fr to 1fr over 260ms and closing in 180ms on the strong ease-out, its words
// fading down into place a beat after. One open at a time by default (a second press closes it); `multiple` lets
// several stay open. v-model is `value` (the open item's value, or a JSON list of them with `multiple`) with `input`
// and `change` events. Compose with <conare-accordion-item>.
export type AccordionValue = string | string[] | null

/**
 * @summary A stack of disclosures, one open at a time or several.
 * @slot - The rows: <conare-accordion-item>.
 * @fires input - A row opened or closed (read `value`).
 * @fires change - A row opened or closed (read `value`).
 */
export class Accordion extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = {
		multiple: { type: Boolean },
		value: { converter: { fromAttribute: (v: string | null) => (v?.trim().startsWith('[') ? JSON.parse(v) : v || null), toAttribute: (v: AccordionValue) => (Array.isArray(v) ? JSON.stringify(v) : v) } },
	}

	/** Several rows stay open. */
	multiple = false
	/** The open row's value, or the list of them with `multiple`. */
	value: AccordionValue = null

	private list() {
		return Array.isArray(this.value) ? this.value : this.value ? [this.value] : []
	}
	/** Whether the row with this value is open (read by the items). */
	isOpen(v: string) {
		return this.list().includes(v)
	}
	/** Opens or closes the row with this value (the items' press). */
	toggle(v: string) {
		const open = this.list()
		if (this.multiple) this.commit(open.includes(v) ? open.filter((x) => x !== v) : [...open, v])
		else this.commit(open.includes(v) ? null : v)
	}

	protected updated(changed: PropertyValues<this>) {
		super.updated(changed)
		if (changed.has('value')) for (const item of this.querySelectorAll<HTMLElement & { requestUpdate(): void }>(tagName('accordion-item'))) item.requestUpdate()
	}

	render() {
		return html`<div data-ds="accordion" class="ds-accordion border-t border-edge"><slot></slot></div>`
	}
}

define('accordion', Accordion)

import { html } from 'lit'
import { ChevronDown } from 'lucide'
import { accordionOf } from '@/elements/controllers/accordion'
import { DsElement, define, uid } from '@/elements/lib/element'
import { icon } from '@/elements/lib/icon'
import styles from 'virtual:tw'

// AccordionItem.vue as <conare-accordion-item>: one row of an accordion: the question as a full-width button (40px,
// 13px soft text that turns ink under the pointer and while open) over a hairline, and the answer under it. The closed
// answer is inert, so its links leave the tab order. `heading` (Vue's `title`) or the `title` slot names the row; the
// default slot is the answer.

/**
 * @summary One row of an accordion.
 * @slot - The answer.
 * @slot title - The question, in place of `heading`.
 */
export class AccordionItem extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { value: {}, heading: {}, disabled: { type: Boolean } }

	/** The value the accordion opens it by. */
	value = ''
	/** The question (Vue's `title`). */
	heading?: string
	disabled = false
	private rowId = uid('accordion')

	render() {
		const ctx = accordionOf(this)
		const open = ctx?.isOpen(this.value) ?? false
		return html`<div data-ds="accordion-item" class="border-b border-edge" data-open=${String(open)}>
			<h3>
				<button id=${`${this.rowId}-head`} type="button" aria-expanded=${String(open)} aria-controls=${`${this.rowId}-body`} ?disabled=${this.disabled} class="flex min-h-row w-full cursor-pointer items-center justify-between gap-3 py-2 text-left type-ui text-fg-soft transition-colors duration-120 ease-standard hover:text-fg aria-expanded:text-fg disabled:cursor-default disabled:text-fg-muted" @click=${() => ctx?.toggle(this.value)}><slot name="title">${this.heading}</slot>${icon(ChevronDown, 'chevron-down', { size: 12, strokeWidth: 1.5, class: 'shrink-0 text-fg-muted transition-[rotate] duration-200 ease-standard motion-reduce:transition-none', attrs: { 'aria-hidden': 'true' } })}</button>
			</h3>
			<div id=${`${this.rowId}-body`} role="region" aria-labelledby=${`${this.rowId}-head`} ?inert=${!open} class="ds-collapse" data-open=${String(open)}>
				<div><div class="ds-collapse-body pb-3 type-ui text-fg-soft"><slot></slot></div></div>
			</div>
		</div>`
	}
}

define('accordion-item', AccordionItem)

/* Vue turns the chevron with the rotate-180 class; here the icon's markup stays the same from one render to the next
   (so its transition runs) and the open row turns it. */
button[aria-expanded="true"] > .lucide-chevron-down { @apply rotate-180; }
/* AccordionItem.vue's <style>, as it is. The console's disclosure (console2.css .v2-collapse): open over 260ms, close in
   180ms, the words fading and settling 6px down with a 2px blur that clears, so the text never pops. Reduced motion: no
   height or move, opacity only. */
.ds-collapse { display: grid; grid-template-rows: 0fr; transition: grid-template-rows var(--ds-duration-slide) var(--ds-easing-out); }
.ds-collapse[data-open="true"] { grid-template-rows: 1fr; transition-duration: var(--ds-duration-collapse); }
.ds-collapse > div { min-height: 0; overflow: hidden; }
.ds-collapse-body { opacity: 0; filter: blur(2px); transform: translateY(-6px); transition: opacity var(--ds-duration-micro) ease, filter var(--ds-duration-micro) ease, transform var(--ds-duration-slide) var(--ds-easing-out); }
.ds-collapse[data-open="true"] .ds-collapse-body { opacity: 1; filter: none; transform: none; transition: opacity var(--ds-duration-settle) ease 40ms, filter var(--ds-duration-settle) ease 40ms, transform var(--ds-duration-collapse) var(--ds-easing-out) 40ms; }
@media (prefers-reduced-motion: reduce) {
  .ds-collapse, .ds-collapse[data-open="true"] { transition: none; }
  .ds-collapse-body, .ds-collapse[data-open="true"] .ds-collapse-body { filter: none; transform: none; transition: opacity var(--ds-duration-micro) ease; }
}

import { tagName } from '@/elements/lib/element'

// useAccordion for elements: what a <conare-accordion> gives its items (whether a value is open, and the press that
// opens or closes it). An item finds its accordion as its closest ancestor, so accordions nest.
export type AccordionContext = { isOpen: (v: string) => boolean, toggle: (v: string) => void }

/** The accordion around an item, or null outside one (or while it is not defined yet: it renders its items again once
 * it is). */
export function accordionOf(item: Element): AccordionContext | null {
	const a = item.parentElement?.closest(tagName('accordion')) as (Element & Partial<AccordionContext>) | null
	return a && typeof a.isOpen === 'function' ? (a as AccordionContext) : null
}
